package com.monisha.sync.ai;

import java.util.Collections;
import java.util.List;

/**
 * Structured semantic metadata generated by AI for a synced document.
 */
public record DocumentAiMetadata(
    String summary,
    List<String> tags
) {
    public DocumentAiMetadata {
        summary = summary != null ? summary.trim() : "";
        tags = tags != null ? List.copyOf(tags) : Collections.emptyList();
    }

    public static DocumentAiMetadata empty() {
        return new DocumentAiMetadata("", List.of());
    }

    public boolean isEmpty() {
        return summary.isEmpty() && tags.isEmpty();
    }
}
